{"itbi": {"devido": true/false, "base": 0, "fundamento": ""}, "integralizacao_imovel": {"valor_recomendado": 0, "ganho_capital_pf": 0}, "pro_labore_minimo_recomendado_mensal": {"Marina": 0, "Felipe": 0, "Luana": 0}, "distribuicao_mensal_pretendida": 50000, "irrf_dividendos_2026_estimado_mensal": 0, "simples_possivel": true/false}

